(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.5)*8+Math.cos(y*0.028+t*0.45)*6;
  const w2y = Math.cos(y*0.032+t*0.55)*8+Math.sin(x*0.025-t*0.4)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75)*40, 0.13, 1.4],
    [200+Math.sin(t*0.38+6)*110, 30+Math.cos(t*0.48+4)*60, 0.05, 2.8],
    [300+Math.cos(t*0.42+1)*90, 100+Math.sin(t*0.58+5)*70, 0.075, 2.0]
  ];
  let aS=0, iS=0, gS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    gS+=Math.cos(d*f*0.5-t*sp*0.8+0.7)*0.5;
  }
  const act=aS/10, inh=iS/10, gra=gS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.03+ang*6-t*0.8)+Math.cos(dist*0.065-ang*2-t*2.1))*0.2;
  const lap = (aS*0.6+gra*0.4)/10;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2+lap*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend=reaction*0.6+cell*0.25+micro, v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,50,90],[18,95,120],[25,150,135],[80,175,100],[170,185,60],[210,155,55],[210,100,60],[180,55,55],[120,30,65],[50,15,50],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=1.0+Math.max(0,Math.sin(reaction*3.14)*0.3)*0.15;
  const m=lum*edge*glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
